=== fault_detect.h ===
/*
 * 电脉卫士 F2：故障判别（规则版先行，NCNN 后期替换）
 * ------------------------------------------------------------
 * 与开发文档 §15.2「五类故障」对齐 + 缺相/断相扩充，规则版先落地（成员 B 兜底）：
 *   0 电弧 / 1 过载 / 2 漏电 / 3 谐波 / 4 短路 / 5 缺相断相
 * 规则依据（占位阈值，待与文档 §5 核对后固化并可经 NVS 配置）：
 *   - 短路：任一相峰值 > 50A  -> Lv3 极危险（必切）；单相模式独立阈 sp_short_peak=100A 峰值
 *   - 漏电：零序 RMS > 0.3A    -> Lv3 极危险（必切）
 *     ⚠️ L5 定位声明：本判据基于【软件合成零序】IN=-(IA+IB+IC)（见 fault_detect.c EG_ENABLE_LEAK_DETECT），
 *     非硬件 ZCT 实测，属【预警级粗判据】（带三相不平衡补偿 0.3 系数、残差≥阈×0.5 才确认）。
 *     不替代 GB/T 13955-2017 / IEC 60364-4-41 规定的 30mA/0.1s 硬件 RCD 人身防护，安装必须保留标准 RCD。
 *   - 电弧：arc_score >= 0.6（异音/高频启发式）-> Lv3（待 NCNN 替换）
 *   - 过载：RMS 持续 > 25A -> Lv3 硬阈必切；> 10A -> Lv2 危险；> 5A -> Lv1 警戒
 *   - 谐波：THD > 15%          -> Lv1 警戒
 *   （过载 L1/L2 阈值支持 fault_detect_set_thresholds() 运行时下发，其余为编译期常量）
 * 输出 fault_event_t（severity 0 Lv0 / 1 Lv1 / 2 Lv2 / 3 Lv3），供 guard_control / UI / 组网 / 上云。
 */
#pragma once
#include "esp_err.h"
#include <stdint.h>
#include "app_core.h"

#ifdef __cplusplus
extern "C" {
#endif

esp_err_t fault_detect_init(void);

/* P1：配电模式（三相/单相/自适应）。单相模式自动禁用「软件合成零序漏电」与「三相缺相」，
 * 并启用「单相缺电单元」（拉闸→电压电流双失 → FAULT_TYPE_POWERLOSS）。 */
typedef enum {
    POWER_MODE_ADAPTIVE     = 0,
    POWER_MODE_THREE_PHASE  = 1,
    POWER_MODE_SINGLE_PHASE = 2,
} power_mode_t;

/* 设置配电模式（同步写 NVS，掉电保持）；返回 ESP_OK */
esp_err_t fault_detect_set_power_mode(power_mode_t mode);

/* 单相独立定值：过载预警/报警(A)、漏电分级(A)、过热上限(℃)。
 * 传 0 表示不修改该项；同步写 NVS。 */
esp_err_t fault_detect_set_single_thresholds(float ol_warn_a, float ol_alarm_a, float leak_a, float temp_max_c);

/* 单相电压/功率定值：欠压(V)、过压(V)、功率上限(kW)。传 0 不修改；同步写 NVS。 */
esp_err_t fault_detect_set_single_power(float u_lo_v, float u_hi_v, float power_kw);

/* L1：单相短路峰值阈值（独立于三相 50A，默认 100A 覆盖 65A 表计量程）。传 0 不修改；写 NVS。 */
esp_err_t fault_detect_set_single_short_peak(float peak_a);

/* 当前是否处于单相诊断模式（显式单相 或 自适应探测到仅 A 相有效负载） */
bool fault_detect_single_active(void);

/* 返回当前配电模式（P1：LCD 主屏徽标 / 健康上报用） */
power_mode_t fault_detect_power_mode(void);

/* 主入口：输入设备状态 -> 判别五类故障 -> 输出事件（无故障返回 false） */
bool fault_detect_run(const device_status_t *st, fault_event_t *out);

/* 过载阈值运行时配置（NVS 加载后下发）；l1>0 且 l2>l1，否则 ESP_ERR_INVALID_ARG */
esp_err_t fault_detect_set_thresholds(float l1, float l2);

/* D6：扩展阈值运行时配置（短路峰值/漏电/电弧得分）。
 * 传 0 或负值表示不修改该参数。arc_score 范围 0~1。
 * 调用后同步写 NVS，下次启动自动加载。 */
esp_err_t fault_detect_set_thresholds_ext(float short_peak, float leak_rms, float arc_score);

/* P1-5：全量阈值运行时配置（三相过载 L1/L2/L3 + 谐波 THD%），供 MQTT config/settings 下行。
 * 键名与 Web SETTING_KEYS(overload_l1/l2/l3/thd)对齐；传 0 表示不修改该字段。 */
esp_err_t fault_detect_set_thresholds_full(float l1, float l2, float l3, float thd);

/* F5: 获取扩展阈值当前值（供 UI 设置页显示） */
void fault_detect_get_thresholds_ext(float *short_peak, float *leak_rms, float *arc_score);

/* P4：获取过载定值当前值（L1 警戒 / L2 危险，供设置页回显） */
void fault_detect_get_overload(float *l1, float *l2);

/* P1：获取单相定值当前值（过载预警/报警、漏电、过热） */
void fault_detect_get_single(float *ol_warn_a, float *ol_alarm_a, float *leak_a, float *temp_max_c);

/* P1：获取单相电压/功率定值当前值（欠压/过压/功率上限） */
void fault_detect_get_single_power(float *u_lo_v, float *u_hi_v, float *power_kw);

/* 最近一次判别的统计值（UI/调试） */
float fault_detect_last_max_rms(void);
float fault_detect_last_max_peak(void);

/* 最近一次判别的等级（fault_severity_t），供 UI 告警等级映射 */
uint8_t fault_detect_last_severity(void);

/* 最近一次判别的故障类型（fault_type_t，无故障=FAULT_TYPE_NONE），供 UI 波形标注 */

=== app_core.h（前60行）===
/*
 * 电脉卫士：核心数据模型与事件日志
 * ------------------------------------------------------------
 * 与开发文档 §7.6「设备状态数据模型与系统整合」保持同构：
 *   device_status_t / fault_event_t 作为采集-判别-执行-UI-组网-上云的统一接口。
 * 事件日志：环形缓冲，UI 事件页与 MQTT 告警上报复用。
 *           SPIFFS 持久化（/spiffs/events.log，最近 16 条，断电可追溯；
 *           读写失败安全降级为纯 RAM）。
 */
#pragma once
#include <stdint.h>
#include <stdbool.h>
#include "esp_err.h"

#ifdef __cplusplus
extern "C" {
#endif

/* ---------- 故障类型（成员 C AI 五类，规则版先行） ---------- */
typedef enum {
    FAULT_TYPE_NONE   = 0xFF, /* 无故障 */
    FAULT_TYPE_ARC    = 0,    /* 电弧 */
    FAULT_TYPE_OVERLOAD = 1,  /* 过载 */
    FAULT_TYPE_LEAK   = 2,    /* 漏电 */
    FAULT_TYPE_HARMONIC = 3,  /* 谐波 */
    FAULT_TYPE_SHORT  = 4,    /* 短路 */
    FAULT_TYPE_PHASELOSS = 5, /* 缺相/断相：三相失衡、某相电流趋近于 0（断相/熔断器熔断） */
    FAULT_TYPE_POWERLOSS = 6, /* 单相停电（单相模式：拉闸/断电 → 电压电流双失，替代三相缺相语义） */
} fault_type_t;

/* ---------- 严重度（全系统 4 级规范，与 lvgl_ui 配色一致） ----------
 * 0 绿(Lv0安全) / 1 黄(Lv1警戒) / 2 橙(Lv2危险) / 3 红+蜂鸣(Lv3极危险) */
typedef enum {
    SEV_LV0_SAFE     = 0,   /* Lv0 安全（绿） */
    SEV_LV1_WATCH    = 1,   /* Lv1 警戒（黄）  */
    SEV_LV2_DANGER   = 2,   /* Lv2 危险（橙）  */
    SEV_LV3_CRITICAL = 3,   /* Lv3 极危险（红 + 蜂鸣） */
} fault_severity_t;

/* ---------- 数据有效性位掩码（device_status_t::flags） ----------
 * 依据判定在采集端（main.cpp acq），按「硬件接线 + 标定 + 演示模式」给出：
 *   置位=该量来自真实采集，可作决策依据；清零=占位/无效（模拟或未就绪），
 *   仅作占位展示，禁止冒充真实量参与判别与指标结论。
 * DST_POWER 不独立置位，恒由 (电压 && 电流) 推导。 */
#define DST_VOLTAGE_VALID  (1u << 0)  /* 电压真实：ADS8688 CH3~CH5 已标定 + SPI 链路健康 */
#define DST_CURRENT_VALID  (1u << 1)  /* 电流真实：真机 ADS8688（非 demo 模拟） */
#define DST_TEMP_VALID     (1u << 2)  /* 温度真实：SHT31 已接线（未接恒 0，视为无数据） */
#define DST_ARC_VALID      (1u << 3)  /* 电弧真实：INMP441 已接线（非 demo 模拟） */
/* [VIRTUAL-PHASE] B/C 相为 A 相合成的虚拟值（台架单相供电）。
 * 与上面四位不同：本位**不是"数据无效"**，而是"数据可用但来源为合成"。
 * 置位语义 = 电压/电流有效位成立，但 B/C 两相读数是镜像出来的，必须带 '*' 标识，
 * 且判别侧须跳过依赖"三相彼此独立"的规则（缺相/不平衡）。 */
#define DST_VIRTUAL_PHASE  (1u << 4)
/* [FIX-ADS-INRMS-2 09-15] **零序可信**：三路电流通道**均已实接**（无悬空相）。
 * 语义：仅当 out->in（零序）可作为漏电判据时置位。
 * 为什么必须独立于 DST_CURRENT_VALID：
 *   DST_CURRENT_VALID 只需"至少一相有真实电流"（过载/短路按相判定，单相即可用）；
 *   而**零序是三相矢量和**，只要有一相悬空，其偏置/拾取噪声就会污染零序
 *   → 单相带载会被误判成接地漏电（真机实测 IA=0.03A / IB=1.92A / IC=0.02A
 *     却算出 i_n=1.92A ≥ 0.3A 阈值 → 上电即 LEAK Lv3 切断）。

    #if CONFIG_ELECTRIC_GUARD_DEMO_MODE
    /* demo 模式跳过 ES8311 声卡：符合 audio.c "demo 不操作任何硬件" 约定。
     * BSP codec init 会一次性创建 I2S TX+RX 通道并分配 DMA 缓冲区，demo 下
     * 该分配因内部 RAM 不足会导致 i2s_rx_channel_start 空指针 panic。 */
    ESP_LOGW(TAG, "demo mode: ES8311 声卡未初始化（提示音/播放省略，烧录安全）");
#endif
    /* P0(09-04)：真机模式 codec init 已后移到 audio_init() 旁（temp_sensor_init
     * 之后）。依据板端实测（12:37 固件启动日志）：bsp_extra_codec_init 在内部
     * RAM 不足时 I2S DMA 分配失败（i2s_alloc_dma_desc ret=257 NO_MEM），且
     * esp_codec_dev_open 内部继续走 ES8311 SCCB(I2C) 长时间重试（同日志
     * "i2c.master: Please check pull-up..."），把 app_main 阻塞在 display init
     * 之前——日志停在 t=1528 I2S_IF 错误后，Direct flush/M1-M4 全部未出现。
     * 显示是安全关键 UI，必须先于可降级的音频建立；codec 失败仅禁提示音，
     * 不影响采集(INMP441)与显示。 */

    bsp_display_cfg_t cfg = {
        .hw_cfg = {
            .hdmi_resolution = BSP_HDMI_RES_NONE,
            .dsi_bus = {
                .lane_bit_rate_mbps = BSP_LCD_MIPI_DSI_LANE_BITRATE_MBPS,
            },
        },
    };
    lv_display_t *disp = lvgl_adapter_init(&cfg);
    assert(disp != nullptr && "Failed to init LVGL adapter");
    bsp_display_backlight_on();

    /* ---- F6/F7 摄像头 pipeline（占位） ----
     * SC2336 MIPI-CSI 驱动已编译(sdkconfig)，但 main 未建 capture pipeline。
     * 接入时需：bsp_camera_new() → MIPI-CSI 初始化 → ISP pipeline → 帧回调。
     * 当前不影响其他功能（驱动编译不等于运行时初始化）。 */

    /* FIX-REBOOT：LVGL 锁重试机制（原单次 3s 超时后裸跑 → 并发 LVGL API 调用 → 对象树损坏）
     * 问题：lock 超时后 main 不持锁就调 lvgl_ui_create()，与 worker 的 lv_timer_handler 并发
     * 操作同一对象树 → 内存损坏 / 死循环 / 随机重启。
     * 方案：重试 3 次 × 5s（共 15s），全部失败则跳过 UI 创建（降级无屏幕但不死机）。 */
    esp_err_t lv_lock_err = ESP_ERR_TIMEOUT;
    bool lv_lock_held = false;
    for (int lock_retry = 0; lock_retry < 3; lock_retry++) {
        lv_lock_err = esp_lv_adapter_lock(5000);   /* 单位是 ms */
        if (lv_lock_err == ESP_OK) {
            lv_lock_held = true;
            break;
        }
        ESP_LOGW(TAG, "[F4] LVGL lock attempt %d/3 TIMEOUT(5s) — flush_cnt=%u trans_done=%u",
                 lock_retry + 1,
                 (unsigned)lvgl_adapter_get_flush_cnt(),
                 (unsigned)lvgl_adapter_get_trans_done_cnt());
    }
    if (!lv_lock_held) {
        ESP_LOGE(TAG, "[F4] LVGL lock 全部超时——跳过 UI 创建（无屏幕降级，不死机）");
        ESP_LOGE(TAG, "[F4] flush_cnt=%u trans_done_cnt=%u — 判断: %s",
                 (unsigned)lvgl_adapter_get_flush_cnt(),
                 (unsigned)lvgl_adapter_get_trans_done_cnt(),
                 (lvgl_adapter_get_flush_cnt() == 0) ? "worker 首帧未进(渲染卡死)" : "DPI 中断丢失");
    }

    /* ---- 业务组件初始化 ---- */
