static esp_err_t camera_capture_stream_by_format(int fd, int type, uint32_t v4l2_format, uint32_t width, uint32_t height)
{
    uint8_t *buffer[BUFFER_COUNT];
#if CONFIG_EXAMPLE_VIDEO_BUFFER_TYPE_USER
