        if (buf.flags & V4L2_BUF_FLAG_DONE) {
            frame_size += buf.bytesused;
            frame_count++;
        }

#if CONFIG_EXAMPLE_VIDEO_BUFFER_TYPE_USER
        buf.m.userptr = (unsigned long)buffer[buf.index];
        buf.length = buffer_size[buf.index];
#endif
