    const float vs = vision_fire_score();
    if (vs > ev_vx.confidence) {
        ev_vx.confidence = vs;
    }
    ESP_LOGW(TAG, "[F6] 视觉交叉验证：%s Lv%d -> Lv3（现场确认明火，score=%.2f）",
             fault_type_name(ev->type), ev->severity, vs);
    audit_log_push(AUDIT_SRC_UI, "vision_escalate", fault_type_name(ev->type));
    ev = &ev_vx;
}

